// Revisa lo que manda el modelo antes de que se aparte una fecha real.
//
// Este nodo no existia (2026-08-27). El insert recibia lo que fuera: una fecha
// del ano pasado se apartaba igual y quedaba bloqueada en Google Calendar, y un
// numero de contacto a medias se guardaba sin que nadie lo notara hasta que un
// asesor intentaba marcar.
//
// Los dos validadores de abajo estan DUPLICADOS -- el de telefono en
// `Calcular Ventana` de agendar_cita, el de fecha tambien en el mensaje de
// FECHA PASADA de verificar_disponibilidad_evento. n8n no deja compartir codigo
// entre workflows. `scripts/probar-telefono.js` corre las dos copias del
// validador de telefono contra la misma tabla de casos y falla si se separan.

// ---------------------------------------------------------------------------
// EL NUMERO DE CONTACTO TIENE QUE QUEDAR MARCABLE (2026-08-27)
// ---------------------------------------------------------------------------
// Antes bastaba con que tuviera 7 digitos. En produccion entraron numeros a
// medias -- el cliente escribe "31502909", le da enviar sin darse cuenta, o
// dicta el numero por audio y la transcripcion se come una cifra -- y la cita
// quedaba agendada igual, con un numero al que nadie puede llamar. El asesor se
// entera cuando marca, no antes, y para entonces el cliente ya se enfrio.
//
// Colombia quedo TODA en 10 digitos con la renumeracion de 2022:
//   celular   3XX XXX XXXX     empieza por 3
//   fijo      60X XXX XXXX     60 + indicativo de region (601 a 608)
// Con indicativo de pais son 12: 57 + esos 10. Se aceptan las dos formas, y
// tambien "+57", "0057" y el numero con espacios, puntos, guiones o parentesis:
// cada quien escribe su numero como quiere y eso no es un error del cliente.
//
// Sale normalizado a E.164 (+57XXXXXXXXXX) para que en Google Calendar y en la
// tabla `citas` quede siempre escrito igual.
//
// OJO: este mismo validador esta DUPLICADO en el nodo `Validar Datos` de
// `separar_fecha_evento`. n8n no deja compartir codigo entre workflows. Si
// tocas uno, toca el otro: `scripts/probar-telefono.js` corre las DOS copias
// contra la misma tabla de casos y falla si dejan de coincidir.
function revisarTelefonoCo(crudo) {
  let d = (crudo ?? '').toString().replace(/\D/g, '');

  if (d === '') return { ok: false, motivo: 'no_dio', vistos: 0 };

  // Indicativo de pais en cualquiera de sus formas -> numero nacional.
  if (d.startsWith('0057')) d = d.slice(4);
  else if (d.startsWith('57') && d.length > 10) d = d.slice(2);
  // Fijo viejo marcado con el 0 de larga distancia: 03XX...
  if (d.length === 11 && d.startsWith('0')) d = d.slice(1);

  // Una sola cifra repetida (3333333333, 0000000000) no es un telefono: es
  // alguien probando, o el modelo rellenando el hueco por su cuenta.
  if (/^(\d)\1+$/.test(d)) return { ok: false, motivo: 'basura', vistos: d.length };

  if (d.length !== 10) {
    return { ok: false, motivo: d.length < 10 ? 'corto' : 'largo', vistos: d.length };
  }
  // 3XX celular, 60X fijo. Cualquier otra cosa con 10 digitos no se puede marcar.
  if (!/^3/.test(d) && !/^60[1-8]/.test(d)) {
    return { ok: false, motivo: 'no_colombiano', vistos: d.length };
  }
  return { ok: true, motivo: 'ok', vistos: d.length, e164: '+57' + d, nacional: d };
}

// El mensaje va de vuelta al AGENTE, no al cliente: se redacta como instruccion
// para que sepa exactamente que pedir y como pedirlo. El "sin hacerlo sentir
// mal" no es adorno -- el cliente no se equivoco, se le quedo a medias -- y sin
// esa linea el modelo contesta "el numero que me diste es invalido".
function pedirTelefonoOtraVez(revision, crudo, esLlamada) {
  const comoPedirlo = esLlamada
    ? '"confirmame por fa a que numero te llamo"'
    : '"por fa me confirmas un numero de contacto"';
  const cierre = ' Pideselo de nuevo con calidez y SIN hacerlo sentir mal: que se te corto, o quieres confirmarlo, nunca "lo escribiste mal". Y vuelve a llamarme con el numero completo.';

  if (revision.motivo === 'no_dio') {
    return `Falta el numero de contacto del cliente. Pideselo antes de agendar: ${comoPedirlo}.`;
  }
  if (revision.motivo === 'corto') {
    return `El numero que te dio el cliente ("${crudo}") tiene ${revision.vistos} digitos y en Colombia son 10. Se le quedo a medias.` + cierre;
  }
  if (revision.motivo === 'largo') {
    return `El numero que te dio el cliente ("${crudo}") tiene ${revision.vistos} digitos y en Colombia son 10 (o 12 con el 57 adelante). Le sobran cifras.` + cierre;
  }
  if (revision.motivo === 'basura') {
    return `El numero que te dio el cliente ("${crudo}") es la misma cifra repetida, no es un telefono real.` + cierre;
  }
  return `El numero que te dio el cliente ("${crudo}") tiene 10 digitos pero no empieza por 3 (celular) ni por 60X (fijo), asi que no se puede marcar en Colombia.` + cierre;
}

// ---------------------------------------------------------------------------
// LA FECHA DEL EVENTO, CUANDO EL CLIENTE LA ESCRIBE MAL (2026-08-27)
// ---------------------------------------------------------------------------
// Dos cosas pasaban en produccion y las dos se ven igual de mal:
//
//   1. El cliente escribe una fecha que YA PASO -- "el 15 de marzo", y marzo
//      quedo atras hace cinco meses -- casi siempre porque esta pensando en el
//      ano que viene y no lo dijo. El agente la tomaba tal cual.
//   2. El agente la "corregia" solo, saltaba al ano siguiente sin avisar, y el
//      cliente terminaba con una fecha apartada que nunca pidio.
//
// Ninguna de las dos se arregla adivinando. Lo que se hace es DEVOLVERLE la
// duda al cliente, con la fecha del ano siguiente ya calculada y nombrada con
// su dia de la semana, para que solo tenga que decir que si. Y con calidez: el
// cliente no cometio un error, se le quedo un dato sin decir.
//
// OJO: `revisarFechaEvento` esta pensado para la fecha del EVENTO, no para la
// de una cita con el asesor. Las citas son a dias vista y sus rechazos de
// tiempo los resuelve `Calcular Libres` ofreciendo horas reales.
function revisarFechaEvento(crudo, ahora) {
  const cruda = (crudo ?? '').toString().trim();
  if (cruda === '') return { ok: false, motivo: 'no_dio' };

  const f = DateTime.fromFormat(cruda, 'yyyy-MM-dd', { zone: 'America/Bogota' });
  if (!f.isValid) return { ok: false, motivo: 'ilegible', cruda };

  const hoy = ahora.startOf('day');
  const nombrar = (d) => d.setLocale('es').toFormat("cccc d 'de' LLLL 'de' yyyy");

  if (f.startOf('day') < hoy) {
    // La misma fecha del ano que viene. Puede caer en otro dia de la semana:
    // por eso se nombra completo, para que el cliente lo verifique de una.
    const sugerida = f.plus({ years: 1 });
    return {
      ok: false,
      motivo: 'pasada',
      cruda,
      legible: nombrar(f),
      hoy_legible: nombrar(ahora),
      sugerida: sugerida.toFormat('yyyy-MM-dd'),
      sugerida_legible: nombrar(sugerida),
      dias_atras: Math.round(hoy.diff(f.startOf('day'), 'days').days),
    };
  }

  // Mas de tres anos adelante es casi siempre un ano tecleado mal (2036 por
  // 2026). No se rechaza a lo bruto: se pregunta.
  if (f.diff(hoy, 'years').years > 3) {
    return { ok: false, motivo: 'lejana', cruda, legible: nombrar(f), hoy_legible: nombrar(ahora) };
  }

  return { ok: true, iso: f.toFormat('yyyy-MM-dd'), legible: nombrar(f) };
}

// El texto va de vuelta al AGENTE. Lleva el guion casi armado a proposito: sin
// el, el modelo contesta "esa fecha ya paso" a secas, que es cierto y suena a
// reproche.
function preguntarPorLaFecha(revision) {
  if (revision.motivo === 'no_dio') {
    return 'Falta la fecha del evento. Pidesela al cliente antes de seguir.';
  }
  if (revision.motivo === 'ilegible') {
    return `No entendi la fecha "${revision.cruda}". Vuelve a preguntarsela al cliente con naturalidad y pasamela en formato YYYY-MM-DD.`;
  }
  if (revision.motivo === 'lejana') {
    return `OJO CON EL ANO. El cliente pidio el ${revision.legible} y hoy es ${revision.hoy_legible}: faltan mas de tres anos, ` +
      'asi que lo mas probable es que el ano se haya tecleado mal. Confirmaselo con calidez antes de seguir, sin decirle que se equivoco.';
  }
  return `FECHA QUE YA PASO. El cliente dijo el ${revision.legible} y hoy es ${revision.hoy_legible}: esa fecha quedo atras hace ${revision.dias_atras} dias. ` +
    'NO la apartes, NO consultes disponibilidad con ella y NO la corrijas por tu cuenta. ' +
    `Preguntale con calidez si se refiere al ${revision.sugerida_legible}, que es esa misma fecha del ano que viene, y dile que apenas te confirme validas la disponibilidad para ese dia. ` +
    'Algo asi, en tus palabras: "Ay, cuentame una cosita para no equivocarme: ' +
    `el ${revision.legible} ya pasó, ¿me estás hablando del ${revision.sugerida_legible}? Confírmame y te valido de una la disponibilidad para esa fecha 🤗". ` +
    'Cuando te confirme, usa la fecha del ano siguiente. Si te dice otra fecha, usa esa.';
}

const entrada = $input.first().json;
const texto = (v) => (v ?? '').toString().trim();

const nombre_sede = texto(entrada.nombre_sede);
const nombre_cliente = texto(entrada.nombre_cliente);
const telefono = texto(entrada.telefono);
const telefono_contacto = texto(entrada.telefono_contacto);

const rechazar = (mensaje) => [{ json: { valido: false, mensaje } }];

if (!nombre_sede) {
  return rechazar('Falta el nombre de la sede. Usa el nombre exacto que te devolvio consultar_precios_sedes.');
}
if (!nombre_cliente) {
  return rechazar('Falta el nombre del cliente. Preguntaselo antes de apartar la fecha: sin nombre no se puede separar.');
}

// La fecha primero: es la que puede dejar un bloqueo real en el calendario.
const revisionFecha = revisarFechaEvento(entrada.fecha, DateTime.now().setZone('America/Bogota'));
if (!revisionFecha.ok) {
  return rechazar(preguntarPorLaFecha(revisionFecha));
}

const revisionTel = revisarTelefonoCo(telefono_contacto);
if (!revisionTel.ok) {
  return rechazar(pedirTelefonoOtraVez(revisionTel, telefono_contacto, false));
}

return [{
  json: {
    valido: true,
    nombre_sede,
    fecha: revisionFecha.iso,
    fecha_legible: revisionFecha.legible,
    nombre_cliente,
    telefono,
    telefono_contacto: revisionTel.e164,
    telefono_contacto_crudo: telefono_contacto,
  },
}];
